/* TechGlam — storefront demonstrativa, sem backend nem pagamento real.
   Os dados de conta e compras são armazenados somente neste navegador.
   Fotos da análise nunca são enviadas ou persistidas. */
(() => {
'use strict';
const STORAGE='techglam-demo-v1';
const DEFAULT_DB={accounts:{},session:null,guestCart:[],guestFavorites:[],guestAnalysis:null,coupon:'',cep:'',messages:[],newsletter:[]};
let db;
try {db={...DEFAULT_DB,...JSON.parse(localStorage.getItem(STORAGE)||'{}')};} catch {db={...DEFAULT_DB};}
const ui={menu:false,drawer:'',chat:false,chatMessages:[{from:'bot',text:'Oi, eu sou a Lila! 💜 Posso te ajudar com produtos, cores e a Glamix. Por onde começamos?'}],filters:{category:'Todas',tone:'todos',maxPrice:2000,sort:'featured',search:''},filterOpen:false,glamixStep:0,glamixPart:'cartuchos',detailImageId:null,detailProductId:null,detailQty:1,authMode:'login',authReturn:'',accountTab:'overview',orderDone:null,analysis:{stage:'photo',fileName:'',photoUrl:'',photoData:null,consent:false,tone:'médio',undertone:'neutro',question:0,answers:[],processing:false}};
const money=v=>(Number(v)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const ico=(name,extra='')=>`<svg class="ico ${extra}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const img=id=>itemById(id)?.image||'./assets/favicon.svg';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch{toast('Não foi possível salvar no navegador.','error');}};
const account=()=>db.session?db.accounts[db.session]||null:null;
const activeCart=()=>account()?account().cart:(db.guestCart??=[]);
const activeFav=()=>account()?account().favorites:(db.guestFavorites??=[]);
const activeAnalysis=()=>account()?.analysis||null||db.guestAnalysis; // replaced below for account isolation
const analysisResult=()=>account()?account().analysis||null:db.guestAnalysis;
const itemById=id=>PRODUCTS.find(p=>p.id===id);
const productImages=p=>p.variants?.length?p.variants.flatMap(v=>v.images.map(image=>({...image,variantId:v.id}))):p.images||[];
const variantById=(p,id)=>p?.variants?.find(v=>v.id===id)||null;
const selectedImage=p=>productImages(p).find(image=>image.id===ui.detailImageId)||productImages(p)[0];
const selectedVariant=p=>variantById(p,selectedImage(p)?.variantId);
const legacyShades={
 'lip-gloss':['Rosa Cristal','Rosa Bebê','Pink Intenso','Cereja Suave','Vermelho Clássico','Coral Vivo','Pêssego Nude','Nude Rosado','Malva Elegante','Cacau Chic'],
 'lip-oil-fruits':['Melancia','Mirtilo','Morango','Pêssego','Cereja']
};
const cartVariant=(it,p)=>{if(!p?.variants?.length)return null;if(it.variantId)return variantById(p,it.variantId);if(it.shade!==undefined){const oldName=legacyShades[p.id]?.[Number(it.shade)];return oldName?p.variants.find(v=>v.name===oldName)||null:p.variants[Number(it.shade)]||null;}return p.variants[0];};
const unitPrice=(it,p)=>p?.price??0;
function normalizeCart(cart){if(!Array.isArray(cart))return [];return cart.filter(it=>{const p=itemById(it.id);return p&&(!p.variants.length||cartVariant(it,p));}).map(it=>{const p=itemById(it.id),variant=cartVariant(it,p);it.variantId=variant?.id||null;it.name=p.name;it.variantName=variant?.name||null;it.image=variant?.images[0]?.src||p.image;it.unitPrice=p.price;it.qty=Math.max(1,Math.floor(Number(it.qty)||1));delete it.shade;return it;});}
db.guestCart=normalizeCart(db.guestCart);db.guestFavorites=(db.guestFavorites||[]).filter(id=>itemById(id));
for(const ac of Object.values(db.accounts)){ac.cart=normalizeCart(ac.cart);ac.favorites=(ac.favorites||[]).filter(id=>itemById(id));if(ac.analysis)ac.analysis.recommended=(ac.analysis.recommended||[]).filter(id=>itemById(id));}
if(db.guestAnalysis)db.guestAnalysis.recommended=(db.guestAnalysis.recommended||[]).filter(id=>itemById(id));
db.coupon='';
const cartCount=()=>activeCart().reduce((n,it)=>n+it.qty,0);
const toast=(msg,type='success')=>{const node=document.createElement('div');node.className='toast '+(type==='error'?'error':'');node.innerHTML=ico(type==='error'?'close':'check')+`<span>${esc(msg)}</span>`;document.querySelector('#toast-root').append(node);setTimeout(()=>node.remove(),3300);};

const quantityInCart=(id,variantId)=>activeCart().find(it=>it.id===id&&it.variantId===variantId)?.qty||0;
function addToCart(id,variantId=null,qty=1){const p=itemById(id);if(!p){toast('Produto não encontrado.','error');return;}const variant=variantId===null?p.variants?.[0]||null:typeof variantId==='number'?p.variants?.[variantId]:variantById(p,variantId);if(p.variants?.length&&!variant){toast('Opção indisponível.','error');return;}const key=variant?.id||null,cart=activeCart(),existing=cart.find(it=>it.id===id&&it.variantId===key);if(existing)existing.qty+=qty;else cart.push({id,variantId:key,name:p.name,variantName:variant?.name||null,image:variant?.images[0]?.src||p.image,unitPrice:p.price,qty});save();render(false);toast(`${p.name}${variant?` — ${variant.name}`:''} adicionado ao carrinho!`);}
function changeQty(id,variantId,delta){const cart=activeCart(),i=cart.findIndex(it=>it.id===id&&it.variantId===variantId);if(i<0)return;cart[i].qty+=delta;if(cart[i].qty<=0)cart.splice(i,1);save();render(false);}
function favorite(id){const list=activeFav(),i=list.indexOf(id);if(i>=0){list.splice(i,1);toast('Removido dos favoritos.');}else{list.push(id);toast('Salvo nos seus favoritos 💜');}save();render(false);}
function totals(){const cart=activeCart(),subtotal=Math.round(cart.reduce((sum,it)=>sum+unitPrice(it,itemById(it.id))*it.qty,0)*100)/100;return{cart,subtotal,discount:0,ship:0,total:subtotal};}
function mergeGuestIntoAccount(ac){ac.cart||=[];ac.favorites||=[];ac.orders||=[];normalizeCart(ac.cart);for(const it of db.guestCart||[]){const old=ac.cart.find(x=>x.id===it.id&&x.variantId===it.variantId);const p=itemById(it.id);if(old)old.qty+=it.qty;else ac.cart.push({...it});}for(const id of db.guestFavorites||[])if(!ac.favorites.includes(id))ac.favorites.push(id);if(db.guestAnalysis&&!ac.analysis)ac.analysis=db.guestAnalysis;db.guestCart=[];db.guestFavorites=[];db.guestAnalysis=null;}
function navRoute(){return decodeURI((location.hash||'#inicio').slice(1));}
function goto(route){ui.drawer='';ui.menu=false;if(location.hash==='#'+route){render();scrollTo({top:0,behavior:'smooth'});}else location.hash=route;}
function headLink(label,route,clazz=''){return `<a class="${clazz} ${navRoute().split('?')[0]===route?'current':''}" href="#${route}">${label}</a>`;}
function brand(){return `<a href="#inicio" class="brand" aria-label="TechGlam, voltar ao início"><span class="brand-mark"><img src="${encodeURI(REAL_IMAGES.brand.logo)}" alt=""/></span><span class="brand-text">Tech<span>Glam</span></span></a>`;}
function header(){return `<div class="announcement">${ico('sparkles')} TECNOLOGIA QUE REALÇA SEU BRILHO</div><header class="header"><div class="container header-main"><button class="icon-action mobile-menu-button" aria-label="Abrir menu" data-action="toggle-menu">${ico('menu')}</button>${brand()}<form class="header-search" id="global-search"><label class="sr-only" for="search-global">Buscar produtos</label><input type="search" id="search-global" name="q" placeholder="O que vai realçar seu brilho hoje?" value="${esc(ui.filters.search)}"/><button type="submit" aria-label="Pesquisar">${ico('search')}</button></form><div class="header-actions"><button class="icon-action" data-action="nav-account" aria-label="Minha conta" title="Minha conta">${ico('user')}</button><button class="icon-action" data-action="go-favs" aria-label="Favoritos" title="Favoritos">${ico('heart')}${activeFav().length?`<span class="bubble">${activeFav().length}</span>`:''}</button><button class="icon-action" data-action="drawer-cart" aria-label="Abrir carrinho" title="Meu carrinho">${ico('bag')}${cartCount()?`<span class="bubble">${cartCount()}</span>`:''}</button></div></div><nav class="nav" aria-label="Menu principal"><div class="container">${headLink('INÍCIO','inicio')}${headLink('TODOS OS PRODUTOS','catalogo')}${headLink('MAQUIAGEM','catalogo?categoria=Paletas%20de%20sombra')}${headLink('LÁBIOS','catalogo?categoria=Lip%20oil')}${headLink('GLAMIX','glamix')}${headLink('LILA GLAM ✦','lila','nav-special')}${headLink('QUEM SOMOS','sobre')}${headLink('CONTATO','contato')}</div></nav><div class="mobile-menu ${ui.menu?'show':''}">${headLink('Início','inicio')}${headLink('Catálogo','catalogo')}${headLink('Glamix','glamix')}${headLink('Lila Glam • Análise de coloração','lila')}${headLink('Quem somos','sobre')}${headLink('Contato','contato')}<form id="mobile-search" class="search-form" style="padding:15px 0"><input name="q" style="width:100%" placeholder="Buscar produtos"/></form></div></header>`;}
function footer(){return `<section class="newsletter"><div class="container"><div><span class="eyebrow">NEWSLETTER TECHGLAM</span><h2>Seu glow, na sua caixa de entrada.</h2><p>Receba novidades e dicas da TechGlam.</p></div><form id="newsletter-form"><label class="sr-only" for="newsletter-email">Seu e-mail</label><input required id="newsletter-email" type="email" name="email" placeholder="Seu melhor e-mail"/><button class="btn btn-dark" type="submit">Quero receber ${ico('arrow')}</button></form></div></section><footer class="footer"><div class="container"><div class="footer-grid"><div>${brand()}<p class="footer-about">Tecnologia que Realça seu Brilho. Acreditamos na beleza de ser quem você é, com inovação, acolhimento e um toque de magia.</p><div class="footer-social"><a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer" aria-label="Instagram (exemplo)">ig</a><a href="https://www.tiktok.com/" target="_blank" rel="noopener noreferrer" aria-label="TikTok (exemplo)">tk</a></div></div><div><h4>EXPLORE</h4><a href="#catalogo">Todos os produtos</a><a href="#glamix">Glamix</a><a href="#lila">Análise de coloração</a><a href="#favoritos">Meus favoritos</a></div><div><h4>TECHGLAM</h4><a href="#sobre">Nossa história</a><a href="#contato">Fale com a gente</a><a href="#contato">Perguntas frequentes</a><a href="#conta">Minha conta</a></div><div><h4>PRECISA DE AJUDA?</h4><span class="footer-text">Seg–Sex · 9h às 18h</span><span class="footer-text">contato@techglam.exemplo</span><span class="footer-text">(11) 4000-0000</span><span class="footer-text">Contatos demonstrativos</span></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} TechGlam. Protótipo de loja — nenhuma compra ou cobrança é real.</span><span>Feito com 💜 para todos os tons de beleza.</span></div></div></footer>`;}
function sectionHeading(kicker,title,route='catalogo',link='Ver todos'){return `<div class="section-heading"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2></div><a class="view-link" href="#${route}">${link} ${ico('arrow')}</a></div>`;}
function pageHeading(kicker,title,description=''){return `<section class="page-heading"><div class="container"><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div></section>`;}
function productCard(p){const fav=activeFav().includes(p.id);return `<article class="product-card"><div class="product-media" data-action="view-product" data-id="${p.id}" role="link" tabindex="0" aria-label="Detalhes de ${esc(p.name)}"><img src="${esc(p.image)}" loading="lazy" alt="${esc(p.images[0].alt)}"/><button class="heart-btn ${fav?'liked':''}" data-action="favorite" data-id="${p.id}" aria-label="${fav?'Retirar':'Adicionar'} ${esc(p.name)} dos favoritos">${ico('heart')}</button></div><div class="product-content"><span class="product-category">${esc(p.category)}</span><a class="product-name" href="#produto/${p.id}">${esc(p.name)}</a><p class="product-description">${esc(p.desc)}</p><div class="price-line"><strong class="price">${money(p.price)}</strong></div><div class="product-footer"><div class="swatches" title="Opções disponíveis">${p.variants.slice(0,5).map(v=>`<span class="swatch" style="background:${esc(v.swatch)}" title="${esc(v.name)}"></span>`).join('')}</div><button class="btn btn-primary card-buy" data-action="add-cart" data-id="${p.id}">${ico('plus')} ${p.variants.length>1?'Escolher':'Adicionar'}</button></div></div></article>`;}
function benefits(){return `<div class="benefits"><div class="container benefits-grid"><div class="benefit">${ico('sparkles')}<div><strong>Cores para você</strong><p>Escolha sua variante favorita</p></div></div><div class="benefit">${ico('heart')}<div><strong>Lila Glam</strong><p>Descubra sugestões de produtos</p></div></div><div class="benefit">${ico('bag')}<div><strong>Glamix</strong><p>Conheça a maquiagem personalizada</p></div></div><div class="benefit">${ico('lock')}<div><strong>Compra demonstrativa</strong><p>Nenhuma cobrança real</p></div></div></div></div>`;}
function sustainability(){return `<section class="section sustainability" aria-labelledby="sustainability-title"><div class="container"><div class="sustainability-intro"><div class="sustainability-copy"><span class="eyebrow">NOSSO OLHAR PARA O FUTURO</span><h2 id="sustainability-title">Beleza que cuida de você e do planeta</h2><p>Na TechGlam, acreditamos que a beleza pode caminhar lado a lado com o cuidado com o meio ambiente.</p><p>Queremos incentivar escolhas mais conscientes e mostrar que pequenos gestos podem fazer uma grande diferença.</p><p>Nossa proposta é valorizar uma beleza que vai além da aparência, promovendo o cuidado, a responsabilidade e o respeito pelo planeta.</p></div><div class="sustainability-art" aria-hidden="true"><svg viewBox="0 0 420 330" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="215" cy="166" r="124" fill="#F8F6F0"/><circle cx="215" cy="166" r="99" stroke="#D8E8D6" stroke-width="1.5"/><path d="M211 278C207 231 211 177 226 108M211 226C181 196 157 171 124 150M219 176C254 162 281 137 300 105" stroke="#6F9478" stroke-width="3" stroke-linecap="round"/><path d="M229 125C252 103 254 81 250 62C228 74 215 94 229 125ZM199 210C167 210 153 197 144 179C168 175 189 185 199 210ZM239 166C273 174 291 160 302 142C277 137 254 146 239 166ZM175 188C167 156 147 143 127 138C129 163 143 182 175 188Z" fill="#B7D4BC" stroke="#6F9478" stroke-width="2" stroke-linejoin="round"/><path d="M125 150C106 122 106 103 117 85C137 105 141 127 125 150Z" fill="#D6E7D2" stroke="#6F9478" stroke-width="2"/><path d="M299 107C302 79 319 62 339 56C341 80 330 99 299 107Z" fill="#D6E7D2" stroke="#6F9478" stroke-width="2"/><g fill="#F4D9DF" stroke="#CE9EAD" stroke-width="2"><ellipse cx="94" cy="228" rx="13" ry="22" transform="rotate(-45 94 228)"/><ellipse cx="124" cy="228" rx="13" ry="22" transform="rotate(45 124 228)"/><ellipse cx="109" cy="212" rx="13" ry="22"/><ellipse cx="109" cy="245" rx="13" ry="22"/><ellipse cx="308" cy="236" rx="10" ry="17" transform="rotate(-45 308 236)"/><ellipse cx="333" cy="236" rx="10" ry="17" transform="rotate(45 333 236)"/><ellipse cx="320" cy="222" rx="10" ry="17"/><ellipse cx="320" cy="249" rx="10" ry="17"/></g><circle cx="109" cy="228" r="10" fill="#E2B893"/><circle cx="320" cy="236" r="8" fill="#E2B893"/><circle cx="80" cy="113" r="4" fill="#C6DCBE"/><circle cx="341" cy="168" r="5" fill="#E9C3CE"/><circle cx="156" cy="70" r="3" fill="#E9C3CE"/></svg></div></div><div class="sustainability-commitments"><span class="eyebrow">COMPROMISSOS QUE QUEREMOS CULTIVAR</span><div class="sustainability-grid"><article class="sustainability-card"><span class="sustainability-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M20 4C12 4 5 7 5 15a5 5 0 0 0 5 5c8 0 11-7 10-16ZM4 21c3-6 7-9 13-12"/></svg></span><h3>Consumo consciente</h3><p>Incentivamos escolhas responsáveis e a valorização de produtos utilizados de maneira consciente.</p></article><article class="sustainability-card"><span class="sustainability-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M19.5 8A8 8 0 0 0 5.4 6M5 2v4.5h4.5M4.5 16A8 8 0 0 0 18.6 18M19 22v-4.5h-4.5"/></svg></span><h3>Descarte responsável</h3><p>Acreditamos na importância de orientar nossos consumidores sobre o descarte adequado de embalagens e resíduos.</p></article><article class="sustainability-card"><span class="sustainability-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M20.5 5.2c-2-2.1-5.2-2.2-7.3-.2L12 6.1 10.8 5c-2.1-2-5.3-1.9-7.3.2-2.1 2.2-2 5.6.1 7.7L12 21l8.4-8.1c2.1-2.1 2.2-5.5.1-7.7Z"/></svg></span><h3>Beleza com propósito</h3><p>Queremos construir uma marca que valorize o bem-estar, o cuidado pessoal e a responsabilidade ambiental.</p></article></div></div></div></section>`;}
const GLAMIX_STEPS=[
 {title:'Escolha suas cores',text:'No aplicativo conectado à Glamix, selecione as tonalidades que deseja explorar.',part:'app'},
 {title:'Personalize sua maquiagem',text:'A Glamix combina cinco pigmentos: vermelho, azul, amarelo, branco e preto, para criar a tonalidade escolhida.',part:'cartuchos'},
 {title:'Produção da maquiagem',text:'Depois da confirmação, o equipamento prepara a combinação e libera o produto pela parte inferior.',part:'saida'},
 {title:'Armazene e utilize',text:'Deposite a maquiagem no pequeno recipiente com tampa para transportar e usar posteriormente.',part:'recipiente'},
 {title:'Aplique com praticidade',text:'Use o espelho da tampa superior e o pincel acoplado para facilitar a aplicação.',part:'espelho'}
];
const GLAMIX_PARTS={
 app:{title:'Aplicativo conectado',text:'Selecione cores e experimente combinações antes de confirmar a preparação.',image:null},
 cartuchos:{title:'Cinco cartuchos de pigmento',text:'Vermelho, azul, amarelo, branco e preto acompanham a impressora.',image:'${encodeURI(REAL_IMAGES.glamix.cartridges)}'},
 espelho:{title:'Espelho e pincel integrados',text:'O espelho fica na tampa superior e o pincel acompanha o equipamento.',image:'${encodeURI(REAL_IMAGES.glamix.open)}'},
 saida:{title:'Saída inferior',text:'A maquiagem preparada é liberada pela parte inferior da Glamix.',image:'${encodeURI(REAL_IMAGES.glamix.open)}'},
 recipiente:{title:'Recipiente portátil',text:'O pequeno recipiente com tampa permite guardar e transportar a maquiagem.',image:'${encodeURI(REAL_IMAGES.glamix.open)}'}
};
function glamixPhone(){return `<div class="glamix-phone" aria-label="Representação ilustrativa do aplicativo Glamix"><div class="glamix-phone-top"></div><small>TECHGLAM • GLAMIX</small><strong>Crie sua cor</strong><p>Experimente combinações</p><div class="glamix-phone-swatches"><i></i><i></i><i></i><i></i><i></i></div><div class="glamix-phone-result"></div><span>● Conectado à Glamix</span></div>`;}
function glamixMix(){return `<div class="glamix-mix" aria-label="Ilustração da combinação de cinco pigmentos"><div class="glamix-pigments"><span style="--pigment:#e34458" aria-label="Vermelho"></span><span style="--pigment:#4c75c9" aria-label="Azul"></span><span style="--pigment:#efca4f" aria-label="Amarelo"></span><span style="--pigment:#f7f5f0" aria-label="Branco"></span><span style="--pigment:#252533" aria-label="Preto"></span></div><div class="glamix-mix-path" aria-hidden="true">↓</div><div class="glamix-mix-result"><span></span><strong>Tonalidade personalizada</strong></div><small>Visualização ilustrativa; a composição depende da escolha no aplicativo.</small></div>`;}
function glamixStepper(compact=false){const step=GLAMIX_STEPS[ui.glamixStep];return `<div class="glamix-stepper ${compact?'compact':''}"><div class="glamix-step-nav" role="group" aria-label="Etapas de funcionamento da Glamix">${GLAMIX_STEPS.map((item,i)=>`<button type="button" data-action="glamix-step" data-step="${i}" class="${i===ui.glamixStep?'active':''}" aria-pressed="${i===ui.glamixStep}" aria-label="Etapa ${i+1}: ${esc(item.title)}"><span>${String(i+1).padStart(2,'0')}</span>${compact?'':`<strong>${esc(item.title)}</strong>`}</button>`).join('')}</div><div class="glamix-step-content" aria-live="polite"><span class="eyebrow">ETAPA ${String(ui.glamixStep+1).padStart(2,'0')} / 05</span><h3>${esc(step.title)}</h3><p>${esc(step.text)}</p>${!compact&&step.part==='app'?glamixPhone():!compact&&step.part==='cartuchos'?glamixMix():''}</div></div>`;}
function glamixVisual(){const positions={espelho:'mirror',cartuchos:'cartridges'};return `<div class="glamix-machine-visual"><img src="${encodeURI(REAL_IMAGES.glamix.open)}" alt="Foto da Impressora Glamix aberta, com espelho, pincel e cinco cartuchos"/>${Object.entries(positions).map(([part,cls])=>`<button type="button" class="glamix-hotspot ${cls} ${ui.glamixPart===part?'active':''}" data-action="glamix-part" data-part="${part}" aria-label="Explorar ${esc(GLAMIX_PARTS[part].title)}" aria-pressed="${ui.glamixPart===part}"><span>+</span></button>`).join('')}<span class="glamix-selected-part" aria-live="polite">${esc(GLAMIX_PARTS[ui.glamixPart].title)}</span></div>`;}
function glamixPartDetail(){const part=GLAMIX_PARTS[ui.glamixPart];return `<div class="glamix-part-detail" aria-live="polite">${part.image?`<img src="${part.image}" alt="Foto da Glamix: ${esc(part.title)}"/>`:glamixPhone()}<div><span class="eyebrow">EXPLORE O EQUIPAMENTO</span><h3>${esc(part.title)}</h3><p>${esc(part.text)}</p></div></div>`;}
function glamixHomeSection(){return `<section class="section glamix-home" aria-labelledby="glamix-home-title"><div class="container"><div class="glamix-home-grid"><div class="glamix-home-copy"><span class="eyebrow">INOVAÇÃO TECHGLAM</span><h2 id="glamix-home-title">Glamix — Sua maquiagem, suas cores, suas regras.</h2><p>Conheça a impressora de maquiagem inteligente da TechGlam. Escolha cores no aplicativo e crie tonalidades exclusivas com liberdade, criatividade e praticidade.</p><div class="glamix-price"><strong>${money(itemById('maquina-glamix').price)}</strong><span>Cinco cartuchos inclusos</span></div>${glamixStepper(true)}<div class="glamix-home-actions"><a href="#glamix" class="btn btn-dark">Explore a Glamix ${ico('arrow')}</a><a href="#produto/maquina-glamix" class="text-link">Ver produto</a></div></div>${glamixVisual()}</div><p class="glamix-disclaimer">A Glamix está pronta para venda. Neste site, o carrinho registra apenas pedidos demonstrativos, sem pagamento ou envio real. Fotos dos produtos TechGlam.</p></div></section>`;}
function glamixPage(){const machine=itemById('maquina-glamix');return `<main class="glamix-page"><section class="glamix-page-hero"><div class="container"><div class="glamix-page-intro"><span class="eyebrow">LINHA TECNOLÓGICA TECHGLAM</span><h1>Glamix — Sua maquiagem, suas cores, suas regras.</h1><p>Conheça a Glamix, a impressora de maquiagem inteligente da TechGlam, criada para transformar a maneira como você explora as cores.</p><p>Com tecnologia de personalização e integração com aplicativo, a Glamix permite criar tonalidades exclusivas, oferecendo mais liberdade, criatividade e praticidade para sua rotina de beleza.</p><div class="glamix-page-buy"><strong>${money(machine.price)}</strong><span>Impressora com cinco cartuchos inclusos</span><button class="btn btn-primary" data-action="add-cart" data-id="maquina-glamix">${ico('bag')} Adicionar ao carrinho demonstrativo</button></div><p class="helper">Linha pronta para venda. Este site não processa pagamento ou envio real; o pedido é apenas demonstrativo.</p></div>${glamixVisual()}</div></section><section class="glamix-benefits section"><div class="container"><div class="glamix-benefit"><span>✦</span><h2>Liberdade</h2><p>Escolha as cores que combinam com seu estilo e sua rotina.</p></div><div class="glamix-benefit"><span>◈</span><h2>Criatividade</h2><p>Explore tonalidades personalizadas a partir dos cinco pigmentos.</p></div><div class="glamix-benefit"><span>✳</span><h2>Praticidade</h2><p>Prepare, armazene e aplique sua maquiagem com o equipamento.</p></div></div></section><section class="section glamix-explore"><div class="container"><div class="glamix-section-heading"><span class="eyebrow">TECNOLOGIA EM CADA DETALHE</span><h2>Explore a Glamix</h2><p>Selecione os pontos sobre a imagem para conhecer cada parte do equipamento.</p></div><div class="glamix-explore-grid">${glamixVisual()}${glamixPartDetail()}</div></div></section><section class="section glamix-how"><div class="container"><div class="glamix-section-heading"><span class="eyebrow">DO APLICATIVO À APLICAÇÃO</span><h2>Como a Glamix funciona</h2><p>Conheça as cinco etapas da sua experiência personalizada.</p></div>${glamixStepper()}</div></section><section class="section glamix-flow"><div class="container"><div class="glamix-section-heading"><span class="eyebrow">FUNCIONAMENTO VISUAL</span><h2>Da escolha à sua maquiagem</h2></div><div class="glamix-flow-diagram" aria-label="Fluxo: aplicativo, cinco pigmentos, impressora e recipiente portátil"><div>${glamixPhone()}<strong>1. Escolha no aplicativo</strong></div><span aria-hidden="true">→</span><div>${glamixMix()}<strong>2. Combine pigmentos</strong></div><span aria-hidden="true">→</span><div><img src="${encodeURI(REAL_IMAGES.glamix.open)}" alt="Foto da Glamix"/><strong>3. Prepare e armazene</strong></div></div></div></section><section class="section glamix-line"><div class="container">${sectionHeading('LINHA GLAMIX','Continue criando','catalogo?categoria=Linha%20Tecnol%C3%B3gica%20TechGlam','Ver toda a linha')}<p>Encontre o kit com cinco cartuchos e os refis individuais nas cinco cores do equipamento.</p><div class="product-grid">${['maquina-glamix','kit-cartuchos','cartucho-individual'].map(id=>productCard(itemById(id))).join('')}</div><p class="helper">A Glamix prepara formulações compatíveis com o equipamento. Outros tipos de cosméticos dependem de formulação, compatibilidade dos cartuchos e testes de segurança específicos.</p><p class="helper">As fotos mostram os produtos TechGlam. O carrinho e o checkout deste site são demonstrativos.</p></div></section></main>`;}
function home(){const featured=['blush-bastao','lip-gloss','paleta-sombra','lip-oil-fruits'].map(itemById);return `<main><section class="hero"><div class="container"><div class="hero-copy"><div class="eyebrow">✦ BELEZA + INOVAÇÃO + VOCÊ</div><h1>Sua beleza.<br>Seu brilho.<br><em>Suas regras.</em></h1><p>Descubra as cores TechGlam e uma nova forma de personalizar sua maquiagem.</p><div class="hero-buttons"><a href="#catalogo" class="btn btn-dark">Explorar coleção ${ico('arrow')}</a><a href="#glamix" class="btn btn-outline">Conhecer a Glamix ${ico('sparkles')}</a></div></div><div class="hero-visual"><div class="hero-blob"></div><img class="hero-model" src="${encodeURI(REAL_IMAGES.brand.lila[2])}" alt="Foto de Lila Glam com maquiagem luminosa"/><span class="hero-circle-word">TECHNOLOGY MEETS BEAUTY ✦</span></div></div></section>${benefits()}<section class="section compact"><div class="container">${sectionHeading('EXPLORE SEU UNIVERSO','Escolha seu próximo glow')}<div class="categories">${CATEGORY_FEATURES.map(c=>`<button class="category-tile" data-action="go-category" data-category="${esc(c.category||c.name)}"><span class="category-visual"><img src="${img(c.product)}" alt="" loading="lazy"/></span><strong>${esc(c.name)}</strong><small>${esc(c.subtitle)}</small></button>`).join('')}</div></div></section><section class="section"><div class="container">${sectionHeading('COLEÇÃO TECHGLAM','Encontre sua próxima cor')}<div class="product-grid">${featured.map(productCard).join('')}</div></div></section><section class="section compact"><div class="container"><div class="lila-banner"><div class="lila-copy"><span class="lila-glow">${ico('sparkles')} CONHEÇA A LILA GLAM</span><h2>Descubra novas possibilidades.</h2><p>Faça a experiência de coloração e receba sugestões de produtos de acordo com suas preferências.</p><a href="#lila" class="btn btn-cream">Conhecer a Lila ${ico('arrow')}</a></div><div class="lila-art"><img src="${encodeURI(REAL_IMAGES.brand.lila[1])}" alt="Lila Glam" loading="lazy"/></div></div></div></section>${glamixHomeSection()}${sustainability()}</main>`;}
function catalog(){const f=ui.filters;let list=PRODUCTS.filter(p=>{if(f.category!=='Todas'&&p.category!==f.category)return false;if(f.tone!=='todos'&&p.tone!==f.tone)return false;if(p.price>f.maxPrice)return false;if(f.search&&!`${p.name} ${p.category} ${p.desc} ${p.variants.map(v=>`${v.name} ${v.description}`).join(' ')}`.toLocaleLowerCase('pt-BR').includes(f.search.toLocaleLowerCase('pt-BR')))return false;return true;});const sorting={featured:()=>0,priceAsc:(a,b)=>a.price-b.price,priceDesc:(a,b)=>b.price-a.price};list.sort(sorting[f.sort]||sorting.featured);return `<main>${pageHeading('UNIVERSO TECHGLAM','Tudo para o seu brilho','Explore maquiagem e a linha tecnológica TechGlam. Veja fotos dos produtos e escolha sua cor.')}<div class="container catalog-layout"><aside class="filter-panel ${ui.filterOpen?'open':''}" aria-label="Filtros de produtos"><div class="between"><h3 style="margin:0">Filtrar por</h3>${ico('filter')}</div><div class="filter-group"><h4>Categoria</h4><label class="check-label"><input type="radio" name="category" data-filter="category" value="Todas" ${f.category==='Todas'?'checked':''}/> Todas as categorias</label>${CATEGORIES.map(cat=>`<label class="check-label"><input type="radio" name="category" data-filter="category" value="${esc(cat)}" ${f.category===cat?'checked':''}/> ${esc(cat)}</label>`).join('')}</div><div class="filter-group"><h4>Tonalidades</h4><select aria-label="Filtrar tonalidades" data-filter="tone"><option value="todos" ${f.tone==='todos'?'selected':''}>Todos os tons</option>${['neutros','rosados','quentes','vibrantes'].map(t=>`<option value="${t}" ${f.tone===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div><div class="filter-group"><h4>Preço máximo</h4><select data-filter="maxPrice" aria-label="Preço máximo">${[50,75,120,500,1650,2000].map(v=>`<option value="${v}" ${f.maxPrice===v?'selected':''}>Até ${money(v)}</option>`).join('')}</select><button class="text-link" data-action="clear-filters">Limpar filtros</button></div></aside><div><div class="catalog-toolbar"><div class="flex"><button class="btn btn-outline btn-sm mobile-filter-toggle" data-action="toggle-filters">${ico('filter')} Filtros</button><p><strong>${list.length}</strong> produtos encontrados${f.search?` para “${esc(f.search)}”`:''}</p></div><label class="flex small" for="sort-products">Ordenar: <select id="sort-products" class="sort-select" data-filter="sort"><option value="featured" ${f.sort==='featured'?'selected':''}>Destaques</option><option value="priceAsc" ${f.sort==='priceAsc'?'selected':''}>Menor preço</option><option value="priceDesc" ${f.sort==='priceDesc'?'selected':''}>Maior preço</option></select></label></div><div class="product-grid">${list.length?list.map(productCard).join(''):`<div class="no-results empty-state"><div class="empty-icon">${ico('search')}</div><h2>Nenhum match por aqui.</h2><p>Tente outros filtros.</p><button class="btn btn-primary" data-action="clear-filters">Limpar filtros</button></div>`}</div></div></div></main>`;}
function notFound(){return `<main class="container" style="padding:70px 0">${empty('search','Ops, essa página não existe.','Que tal voltar para descobrir seus novos favoritos?','inicio','Voltar ao início')}</main>`;}
function empty(icon,title,desc,route,label){return `<div class="empty-state"><div class="empty-icon">${ico(icon)}</div><h2>${title}</h2><p>${desc}</p><a class="btn btn-primary" href="#${route}">${label} ${ico('arrow')}</a></div>`;}
function cartLine(it,short=false){const p=itemById(it.id);if(!p)return '';const variant=cartVariant(it,p),variantId=variant?.id||'',name=it.name||p.name,variantName=it.variantName||variant?.name;return `<div class="cart-line"><a class="cart-thumb" href="#produto/${p.id}"><img src="${esc(it.image||variant?.images[0]?.src||p.images?.[0]?.src||img(p.id))}" alt="${esc(name)}${variantName?` — ${esc(variantName)}`:''}"/></a><div><h3><a href="#produto/${p.id}">${esc(name)}${variantName?` — ${esc(variantName)}`:''}</a></h3>${variantName?`<p>Opção: ${esc(variantName)}</p>`:''}<div class="qty-ctrl"><button data-action="change-qty" data-id="${p.id}" data-variant-id="${esc(variantId)}" data-delta="-1" aria-label="Diminuir quantidade de ${esc(name)}${variantName?` ${esc(variantName)}`:''}">${ico('minus')}</button><span>${it.qty}</span><button data-action="change-qty" data-id="${p.id}" data-variant-id="${esc(variantId)}" data-delta="1" aria-label="Aumentar quantidade de ${esc(name)}${variantName?` ${esc(variantName)}`:''}">${ico('plus')}</button></div></div><div class="line-end"><strong>${money(unitPrice(it,p)*it.qty)}</strong><button data-action="remove-cart" data-id="${p.id}" data-variant-id="${esc(variantId)}" aria-label="Remover ${esc(name)}${variantName?` ${esc(variantName)}`:''}" title="Remover">${ico('trash')}</button></div></div>`;}
function cartTotals(t){return `<div class="totals"><div class="total-row"><span>Produtos (${cartCount()} itens)</span><strong>${money(t.subtotal)}</strong></div><div class="total-row total-final"><span>Total dos produtos</span><span>${money(t.total)}</span></div><p class="helper">Frete não calculado neste protótipo. Nenhuma cobrança ou entrega é realizada.</p></div>`;}
function summaryPanel(t,checkout=false){return `<aside class="panel"><h3>Resumo do pedido</h3><p class="helper">Preços de catálogo informados pela TechGlam.</p><div class="divider"></div>${cartTotals(t)}<div class="spacer"></div>${checkout?'<p class="notice warning">Ambiente demonstrativo: esta etapa não realiza cobrança, pagamento ou envio de produtos.</p>':`<button data-action="checkout" class="btn btn-dark full">Finalizar pedido demonstrativo ${ico('arrow')}</button>`}</aside>`;}
function cartPage(){const t=totals();return `<main>${pageHeading('MINHAS ESCOLHAS','Meu carrinho','Confira os produtos selecionados e seus preços.')}<div class="container">${t.cart.length?`<div class="two-column"><section class="panel"><div class="between"><h2>Seus produtos (${cartCount()})</h2><button class="text-link" data-action="clear-cart">Limpar carrinho</button></div>${t.cart.map(it=>cartLine(it)).join('')}<a class="text-link" href="#catalogo">← Continuar comprando</a></section>${summaryPanel(t)}</div>`:`<div style="padding:44px 0 80px">${empty('bag','Seu carrinho está esperando por você.','Que tal escolher alguns itens para dar aquele up no seu brilho?','catalogo','Explorar produtos')}</div>`}</div></main>`;}
function favoritesPage(){const list=activeFav().map(itemById).filter(Boolean);return `<main>${pageHeading('SEUS DESEJOS','Minha wishlist','Guarde as suas descobertas favoritas para encontrar seu próximo match.')}<div class="container section">${list.length?`<div class="product-grid">${list.map(productCard).join('')}</div><p class="helper" style="margin-top:18px">${account()?'Favoritos vinculados ao perfil demonstrativo.':'Entre na sua conta para associar os favoritos ao seu perfil.'}</p>`:empty('heart','Sua lista ainda está vazia.','Quando algum produto conquistar seu coração, toque no ícone de coração para guardar.','catalogo','Encontrar meus favoritos')}</div></main>`;}
function checkoutPage(){const t=totals();if(!t.cart.length)return `<main>${pageHeading('SEU PEDIDO','Finalização')}<div class="container section">${empty('bag','Seu carrinho está vazio.','Adicione itens para iniciar um pedido demonstrativo.','catalogo','Ver catálogo')}</div></main>`;if(!account()){ui.authReturn='checkout';return loginPage();}return `<main>${pageHeading('QUASE LÁ','Finalizar pedido','Revise seus dados para concluir uma compra simulada, sem qualquer cobrança.')}<div class="container two-column"><section class="panel"><div class="checkout-stages"><span class="active">1 • Entrega</span><span class="active">2 • Pagamento</span><span>3 • Confirmação</span></div><h2>Dados para entrega</h2><form id="checkout-form"><div class="form-grid"><div class="form-field"><label for="check-name">Nome completo</label><input required id="check-name" name="name" value="${esc(account().name)}" minlength="3"/></div><div class="form-field"><label for="check-phone">Telefone</label><input required id="check-phone" name="phone" type="tel" pattern="[0-9() +\-]{10,18}" placeholder="(11) 99999-9999" value="${esc(account().phone||'')}"/></div><div class="form-field"><label for="check-cep">CEP</label><input required id="check-cep" name="cep" pattern="[0-9]{5}-?[0-9]{3}" placeholder="00000-000" value="${esc(db.cep)}"/></div><div class="form-field"><label for="check-number">Número</label><input required id="check-number" name="number" placeholder="Nº" value="${esc(account().address?.number||'')}"/></div></div><div class="form-field"><label for="check-street">Rua / avenida</label><input required id="check-street" name="street" placeholder="Endereço completo" value="${esc(account().address?.street||'')}"/></div><div class="form-grid"><div class="form-field"><label for="check-city">Cidade</label><input required id="check-city" name="city" value="${esc(account().address?.city||'')}"/></div><div class="form-field"><label for="check-state">Estado (UF)</label><input required id="check-state" name="state" maxlength="2" minlength="2" pattern="[A-Za-z]{2}" placeholder="SP" value="${esc(account().address?.state||'')}"/></div></div><div class="divider"></div><h2>Forma de pagamento</h2><div class="form-field"><label for="payment">Escolha um método (simulado)</label><select id="payment" name="payment"><option value="Pix demonstrativo">Pix — demonstração</option><option value="Cartão demonstrativo">Cartão de crédito — demonstração</option><option value="Boleto demonstrativo">Boleto — demonstração</option></select></div><div class="notice warning">${ico('lock')} Nenhum número de cartão, chave Pix ou dado financeiro será solicitado. O botão abaixo gera apenas um pedido fictício.</div><div class="spacer"></div><button class="btn btn-primary full" type="submit">Confirmar pedido simulado • ${money(t.total)} em produtos ${ico('arrow')}</button></form>${checkoutItemReview(t)}</section>${summaryPanel(t,true)}</div></main>`;}
function successPage(){const id=ui.orderDone||db.lastOrderId;return `<main><div class="container order-success"><div class="symbol">${ico('check')}</div><span class="eyebrow">EXPERIÊNCIA FINALIZADA</span><h1>Seu brilho foi confirmado!</h1><p>Pedido <strong>${esc(id||'TG-DEMO')}</strong> criado com sucesso <strong>apenas para demonstração</strong>. Não houve pagamento, envio real ou cobrança. Você pode consultá-lo no histórico da conta.</p><div class="flex" style="justify-content:center;flex-wrap:wrap"><a href="#conta" class="btn btn-primary">Ver meus pedidos ${ico('arrow')}</a><a href="#catalogo" class="btn btn-outline">Voltar à loja</a></div></div></main>`;}
function loginPage(){if(account()&&navRoute()==='login'){return accountPage();}const mode=ui.authMode;return `<main><div class="auth-wrapper"><div class="auth-art"><div class="auth-art-text"><span class="eyebrow light">SEU GLOW COMEÇA AQUI</span><h2>Seu universo de beleza, só seu.</h2></div><img src="${encodeURI(REAL_IMAGES.brand.lila[2])}" alt="Foto de Lila Glam"/></div><div class="auth-content"><span class="eyebrow">BEM-VINDA À TECHGLAM</span><h1>${mode==='register'?'Crie sua conta.':mode==='forgot'?'Sua senha.':'Que bom te ver!'}</h1><p>Salve seus favoritos, conheça seus matches e acompanhe pedidos demonstrativos.</p><div class="auth-switch"><button type="button" class="${mode==='login'?'active':''}" data-action="auth-mode" data-mode="login">Entrar</button><button type="button" class="${mode==='register'?'active':''}" data-action="auth-mode" data-mode="register">Criar conta</button></div><div class="notice warning" style="margin-bottom:21px">Conta demonstrativa salva apenas no seu navegador. Não use uma senha real ou reutilizada; não há servidor ou recuperação por e-mail.</div>${mode==='register'?`<form id="register-form"><div class="form-field"><label for="reg-name">Seu nome</label><input required id="reg-name" name="name" minlength="2" autocomplete="name" placeholder="Como podemos te chamar?"/></div><div class="form-field"><label for="reg-email">E-mail</label><input required id="reg-email" name="email" type="email" autocomplete="email" placeholder="voce@exemplo.com"/></div><div class="form-field"><label for="reg-pass">Senha exclusiva para esta demo</label><input required id="reg-pass" name="password" type="password" minlength="8" autocomplete="new-password" placeholder="No mínimo 8 caracteres"/></div><button type="submit" class="btn btn-primary full">Criar conta demonstrativa ${ico('arrow')}</button></form>`:mode==='forgot'?`<form id="recover-form"><div class="form-field"><label for="recover-email">E-mail cadastrado nesta demonstração</label><input id="recover-email" name="email" type="email" required/></div><div class="form-field"><label for="recover-pass">Nova senha local (mínimo 8 caracteres)</label><input id="recover-pass" name="password" type="password" minlength="8" required/></div><p class="helper">Fluxo exclusivo da demonstração: não há verificação de identidade, e a senha muda somente neste navegador.</p><button class="btn btn-primary full" type="submit">Redefinir nesta demonstração</button></form>`:`<form id="login-form"><div class="form-field"><label for="login-email">E-mail</label><input required id="login-email" name="email" type="email" autocomplete="email" placeholder="seu@email.com"/></div><div class="form-field"><label for="login-pass">Senha</label><input required id="login-pass" name="password" type="password" autocomplete="current-password" placeholder="Sua senha demonstrativa"/></div><div class="between" style="margin-bottom:18px"><span class="helper">Ainda não tem conta? Cadastre-se.</span><button type="button" class="text-link tiny" data-action="auth-mode" data-mode="forgot">Esqueci minha senha</button></div><button class="btn btn-primary full" type="submit">Entrar na minha conta ${ico('arrow')}</button></form>`}</div></div></main>`;}
function accountPage(){const user=account();if(!user){ui.authReturn='conta';return loginPage();}const tab=ui.accountTab;let content='';
 if(tab==='overview'){content=`<span class="eyebrow">BEM-VINDA DE VOLTA</span><h2>Oi, ${esc(user.name.split(' ')[0])}! ✨</h2><p class="text-muted small">Este é seu cantinho TechGlam. Seu brilho merece um espaço especial.</p><div class="values-grid" style="margin:24px 0;grid-template-columns:repeat(3,1fr)"><div class="value-card" style="padding:20px"><strong style="font-size:23px">${(user.orders||[]).length}</strong><p>Pedidos demo</p></div><div class="value-card" style="padding:20px"><strong style="font-size:23px">${user.favorites?.length||0}</strong><p>Favoritos</p></div><div class="value-card" style="padding:20px"><strong style="font-size:23px">${user.analysis?'1':'0'}</strong><p>Análises</p></div></div><div class="notice">${user.analysis?'Sua análise da Lila está salva nesta conta, com sugestões de produtos.':'Faça sua análise com a Lila Glam para receber sugestões de produtos.'}</div><div class="spacer"></div><a class="btn btn-primary" href="#lila">${user.analysis?'Refazer análise':'Conhecer a Lila'} ${ico('sparkles')}</a>`;}
 if(tab==='orders'){content=`<h2>Meus pedidos</h2><p class="text-muted small">Histórico de compras simuladas neste navegador.</p>${user.orders?.length?user.orders.map(o=>`<div class="order-card"><div class="between"><strong>${esc(o.id)}</strong><span class="tag">Pedido simulado</span></div><p>${new Date(o.date).toLocaleDateString('pt-BR')} • ${o.items.length} produtos • ${money(o.total)} • ${esc(o.payment)}</p><ul class="order-items">${o.items.map(orderItemLabel).join("")}</ul></div>`).join(''):'<p class="notice">Nenhum pedido ainda. Que tal descobrir a coleção?</p>'}`;}
 if(tab==='profile'){content=`<h2>Meus dados</h2><p class="text-muted small">Dados pessoais salvos somente neste navegador.</p><form id="profile-form"><div class="form-field"><label for="profile-name">Nome</label><input required id="profile-name" name="name" value="${esc(user.name)}"/></div><div class="form-field"><label for="profile-email">E-mail cadastrado</label><input id="profile-email" value="${esc(user.email)}" readonly/></div><div class="form-field"><label for="profile-phone">Telefone</label><input id="profile-phone" name="phone" placeholder="(11) 99999-9999" value="${esc(user.phone||'')}"/></div><div class="form-field"><label for="profile-street">Endereço</label><input id="profile-street" name="street" value="${esc(user.address?.street||'')}"/></div><div class="form-grid"><div class="form-field"><label for="profile-number">Número</label><input id="profile-number" name="number" value="${esc(user.address?.number||'')}"/></div><div class="form-field"><label for="profile-city">Cidade</label><input id="profile-city" name="city" value="${esc(user.address?.city||'')}"/></div></div><div class="form-field"><label for="profile-state">UF</label><input id="profile-state" name="state" maxlength="2" value="${esc(user.address?.state||'')}"/></div><button class="btn btn-primary" type="submit">Salvar alterações</button></form><div class="divider"></div><button class="text-link" data-action="delete-account">Excluir meu cadastro local e meus dados</button><p class="helper">A exclusão apaga este perfil, pedidos, favoritos e histórico da Lila deste navegador.</p>`;}

 if(tab==='analysis'){const a=user.analysis;content=`<h2>Minha análise Lila Glam</h2>${a?`<div class="result-banner"><div class="result-color" style="background:${a.skinColor||'#bf9587'}"></div><div><h3>Tom ${esc(a.tone)} • subtom ${esc(a.undertone)}</h3><p>Estimativa experimental feita localmente em ${new Date(a.date).toLocaleDateString('pt-BR')}.</p></div></div><p class="small text-muted" style="margin:20px 0">Produtos sugeridos: ${a.recommended.filter(id=>itemById(id)).map(id=>esc(itemById(id).name)).join(', ')}.</p>`:'<p class="notice">Você ainda não realizou a experiência de coloração.</p>'}<div class="spacer"></div><a href="#lila" class="btn btn-primary">${a?'Refazer':'Começar'} análise ${ico('arrow')}</a>${a?`<div class="spacer"></div><button data-action="delete-analysis" class="text-link">Excluir resultado salvo da Lila</button>`:''}`;}
 const tabs=[['overview','Visão geral','sparkles'],['orders','Pedidos','bag'],['profile','Meus dados','user'],['analysis','Lila Glam','heart']];return `<main>${pageHeading('ÁREA PESSOAL','Minha conta','Um espaço pensado para você.')}<div class="container account-grid"><aside class="account-side">${tabs.map(([id,label,icon])=>`<button class="${id===tab?'active':''}" data-action="account-tab" data-tab="${id}">${ico(icon)} ${label}</button>`).join('')}<button data-action="logout">${ico('close')} Sair</button></aside><section class="account-main">${content}</section></div></main>`;}
function lilaPage(){const a=ui.analysis;let body='';if(a.stage==='photo'){body=`<span class="eyebrow">ETAPA 01 • SEU ROSTO, SUA HISTÓRIA</span><h2>Vamos descobrir seus tons?</h2><p>Envie uma fotografia para uma estimativa experimental de luminosidade e subtom. Depois, a gente conhece seus gostos para criar sugestões só suas!</p><div class="notice warning"><strong>Transparência:</strong> esta demonstração faz uma análise simples de pixels no navegador, não usa inteligência artificial nem reconhece rostos. Os resultados podem estar incorretos; você pode ajustar os valores antes de continuar.</div><div class="analysis-guidance"><div class="guidance-item">${ico('check')} Rosto visível, sem maquiagem e sem filtros</div><div class="guidance-item">${ico('check')} Luz natural, sem sombras fortes</div><div class="guidance-item">${ico('check')} Foto centralizada, olhando para frente</div><div class="guidance-item">${ico('check')} JPG, PNG ou WebP • até 6 MB</div></div><label class="consent"><input id="photo-consent" type="checkbox" ${a.consent?'checked':''}/> <span><strong>Concordo com o processamento local da minha foto.</strong> A imagem é mantida somente na memória desta aba para exibição e estimativa, não é enviada, não é salva no armazenamento do navegador e é descartada ao sair/recarregar. Apenas o resultado textual poderá ser salvo.</span></label><div class="upload-area">${ico('camera')}<strong>Escolha sua foto</strong><p>A estimativa funciona melhor com o rosto centralizado e fundo neutro.</p><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Selecionar foto do rosto" ${a.consent?'':'disabled'}/></div>${a.photoUrl?`<img class="photo-preview" src="${a.photoUrl}" alt="Prévia local da foto selecionada"/><p class="center tiny">${esc(a.fileName)} • processada somente neste navegador</p><div class="form-grid"><div class="form-field"><label for="tone-override">Tom estimado (ajustável)</label><select id="tone-override" data-analysis="tone">${['claro','médio','profundo'].map(t=>`<option value="${t}" ${a.tone===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div><div class="form-field"><label for="undertone-override">Subtom estimado (ajustável)</label><select id="undertone-override" data-analysis="undertone">${['quente','neutro','frio'].map(t=>`<option value="${t}" ${a.undertone===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div></div><p class="helper">A luz e o fundo da imagem afetam significativamente a estimativa.</p>`:''}<div class="analysis-controls"><span class="helper">${a.photoUrl?'✓ Foto carregada':'Aguardando foto e consentimento'}</span><button class="btn btn-primary" data-action="analysis-next" ${a.photoUrl?'':'disabled'}>${a.processing?'Analisando...':'Continuar para o quiz'} ${ico('arrow')}</button></div>`;}
 if(a.stage==='quiz'){const q=QUESTIONS[a.question];body=`<div class="between"><span class="eyebrow">ETAPA 02 • O SEU JEITO DE BRILHAR</span><span class="quiz-counter">${a.question+1} / ${QUESTIONS.length}</span></div><h2 style="margin-top:15px">${esc(q.title)}</h2><p>Não existe resposta certa: a maquiagem deve combinar com você, e não o contrário.</p><div style="margin-top:26px">${q.options.map((opt,i)=>`<button class="quiz-option ${a.answers[a.question]===i?'selected':''}" data-action="quiz-answer" data-option="${i}"><span class="radio-visual"></span>${esc(opt)}</button>`).join('')}</div><div class="analysis-controls"><button class="btn btn-outline" data-action="quiz-back">Voltar</button><button class="btn btn-primary" data-action="quiz-next" ${a.answers[a.question]===undefined?'disabled':''}>${a.question===QUESTIONS.length-1?'Ver meu resultado':'Próxima pergunta'} ${ico('arrow')}</button></div>`;}
 if(a.stage==='result'){const res=analysisResult();if(!res){a.stage='photo';return lilaPage();}const combos=res.tonePref==='quentes'?'pêssego, terracota e cobre':res.tonePref==='vibrantes'?'ameixa, berries e toques de lilás':res.tonePref==='neutros'?'nude, marrom e malva':'rosé, malva e rosa queimado';body=`<span class="eyebrow">ETAPA 03 • MATCH ENCONTRADO</span><h2>Seu brilho é único. ✨</h2><p>Com base na estimativa fotográfica experimental e nas suas preferências, aqui vai uma seleção feita para o seu estilo.</p><div class="result-banner"><div class="result-color" style="background:${esc(res.skinColor)}"></div><div><h3>Tom ${esc(res.tone)} • subtom ${esc(res.undertone)}</h3><p>Estimativa visual não clínica e não definitiva. Iluminação, maquiagem e câmera podem alterar o resultado.</p></div></div><div class="result-list"><strong>Seu mapa de cores:</strong> explore ${esc(combos)}. ${res.finish==='Iluminado / glow'?'Acabamentos luminosos podem destacar os pontos altos do rosto.':res.finish==='Matte aveludado'?'Texturas mais aveludadas podem criar um visual sofisticado.':'Texturas leves ajudam a manter um acabamento equilibrado.'} Teste as cores com calma: você decide o que te faz sentir bem.</div><div class="between" style="margin-top:26px"><h3 style="margin:0">Seus matches TechGlam</h3></div><div class="result-products">${res.recommended.map(id=>{const p=itemById(id);return `<div class="rec-card"><img src="${img(id)}" alt="${esc(p.name)}"/><div class="rec-content"><h4>${esc(p.name)}</h4><p>${esc(recommendReason(p,res))}</p><strong>${money(p.price)}</strong><button class="btn btn-primary btn-sm" data-action="add-cart" data-id="${id}">Escolher variante ${ico('arrow')}</button></div></div>`;}).join('')}</div><p class="helper" style="margin-top:13px">Sugestões ilustrativas. Nenhum dado fotográfico foi guardado.</p><div class="analysis-controls"><a href="#catalogo" class="btn btn-outline">Ver catálogo</a><button class="btn btn-dark" data-action="reset-analysis">Refazer análise ${ico('arrow')}</button></div>`;}
 const dots=a.stage==='photo'?1:a.stage==='quiz'?2:3;return `<main><section class="analysis-intro"><div class="container"><div><span class="eyebrow">LILA GLAM • EXPERIÊNCIA PERSONALIZADA</span><h1>Descubra seu <em style="color:#976abd">color match.</em></h1><p>Sua beleza tem mil possibilidades. A Lila te ajuda a explorar combinações que fazem sentido para você — com transparência e muito carinho.</p><span class="tag">${ico('sparkles')} Versão demonstrativa • sem IA real</span></div><img src="${encodeURI(REAL_IMAGES.brand.lila[0])}" alt="Lila Glam, assistente virtual"/></div></section><div class="container"><div class="step-track" aria-label="Progresso da análise: etapa ${dots} de 3"><div class="step-dot done"></div><div class="step-dot ${dots>1?'done':''}"></div><div class="step-dot ${dots>2?'done':''}"></div></div><div class="analysis-box">${body}</div></div></main>`;}
function recommendReason(p,r){const map={'Blush em bastão':'Fórmula prática para modular intensidade e realçar as maçãs do rosto.','Paletas de blush':'Versatilidade para variar tons de blush no mesmo look.','Blush líquido':'Textura leve que combina com sua rotina e acabamento preferido.','Lip oil':'Brilho confortável para completar um visual luminoso.','Lip gloss':'Cor e brilho para destacar os lábios.','Paletas de sombra':'Cores para experimentar combinações que combinam com suas preferências.','Pincéis e esponjas':'Ajuda a criar o acabamento do jeito que você gosta.'};return map[p.category]||'Acessório para trazer mais praticidade à sua rotina.';}
function makeRecommendations(a){const answers=a.answers,tonePref=['neutros','rosados','quentes','vibrantes'][answers[2]]||'rosados',desired=answers[3];const special=[['blush-bastao','blush-liquido','paleta-blush'],['lip-gloss','lip-oil-fruits'],['paleta-sombra'],['kit-pinceis','kit-esponjas']][desired]||[];const byTone={neutros:['paleta-sombra','kit-pinceis','lip-gloss'],rosados:['blush-bastao','lip-gloss','paleta-blush'],quentes:['blush-liquido','paleta-sombra','lip-oil-fruits'],vibrantes:['lip-oil-fruits','lip-gloss','paleta-sombra']};const recs=[...new Set([...special,...byTone[tonePref]])].slice(0,3);return{tone:a.tone,undertone:a.undertone,skinColor:a.photoData?.skinColor||'#bf9587',tonePref,finish:QUESTIONS[4].options[answers[4]],recommended:recs,answers:[...answers],date:new Date().toISOString()};}
function aboutPage(){return `<main><section class="story-hero"><div class="container"><div><span class="eyebrow">NOSSA HISTÓRIA, NOSSO PROPÓSITO</span><h1>Beleza é ser <em style="color:#9466b7">você</em> em todas as suas versões.</h1><p>A TechGlam nasce de uma ideia simples: a tecnologia pode aproximar a beleza das pessoas, nunca impor padrões. Somos uma marca-conceito que combina maquiagem, inovação e personalização para celebrar cada tom, textura e estilo.</p><a href="#catalogo" class="btn btn-dark">Conheça a coleção ${ico('arrow')}</a></div><div class="story-visual"><img src="${encodeURI(REAL_IMAGES.brand.lila[2])}" alt="Foto de Lila Glam"/></div></div></section><section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">O QUE NOS MOVE</span><h2>Uma nova maneira de se sentir linda.</h2></div></div><div class="values-grid"><div class="value-card">${ico('heart')}<h3>Missão</h3><p>Tornar a maquiagem mais acessível e personalizada, respeitando diferentes tons de pele, identidades e estilos.</p></div><div class="value-card">${ico('sparkles')}<h3>Visão</h3><p>Ser referência em experiências de beleza inclusivas, inteligentes e acolhedoras.</p></div><div class="value-card">${ico('check')}<h3>Valores</h3><p>Diversidade, autoestima, respeito, criatividade, transparência e responsabilidade no uso da tecnologia.</p></div></div></div></section><section class="section compact" style="background:#f4eaf9"><div class="container"><div class="lila-banner"><div class="lila-copy"><span class="eyebrow light">TECNOLOGIA COM PROPÓSITO</span><h2>Personalização sem padrões.</h2><p>A Lila Glam foi idealizada para ajudar cada pessoa a descobrir novas possibilidades de cor. A versão atual é uma experiência demonstrativa: estimativas não substituem avaliações profissionais e não devem definir sua beleza.</p><a class="btn btn-cream" href="#lila">Conheça a Lila ${ico('arrow')}</a></div><div class="lila-art"><img src="${encodeURI(REAL_IMAGES.brand.lila[1])}" alt="Lila Glam"/></div></div></div></section></main>`;}
function contactPage(){return `<main>${pageHeading('ESTAMOS AQUI POR VOCÊ','Vamos conversar?','Dúvida, sugestão ou vontade de bater um papo sobre maquiagem? Nosso espaço demonstrativo de atendimento está aberto.')}<div class="container contact-grid"><section class="contact-card"><span class="eyebrow">FALE COM A TECHGLAM</span><h2>Conte com a gente.</h2><p class="small text-muted">Preencha o formulário abaixo. Nesta versão, a mensagem é registrada somente no navegador; ela não é enviada a ninguém.</p><form id="contact-form"><div class="form-grid"><div class="form-field"><label for="contact-name">Nome</label><input id="contact-name" name="name" placeholder="Seu nome" minlength="2" required/></div><div class="form-field"><label for="contact-email">E-mail</label><input id="contact-email" name="email" type="email" placeholder="seu@email.com" required/></div></div><div class="form-field"><label for="contact-subject">Assunto</label><select name="subject" id="contact-subject"><option>Dúvida sobre produtos</option><option>Frete e entrega</option><option>Parcerias</option><option>Outros assuntos</option></select></div><div class="form-field"><label for="contact-msg">Sua mensagem</label><textarea id="contact-msg" name="message" placeholder="Escreva aqui..." minlength="10" required></textarea></div><button class="btn btn-primary" type="submit">Registrar mensagem demo ${ico('arrow')}</button></form></section><aside><div class="contact-card"><h2>Fique pertinho.</h2><span class="tag">Dados de contato fictícios</span><div class="info-item">${ico('mail')}<div><h3>E-mail</h3><p>contato@techglam.exemplo</p></div></div><div class="info-item">${ico('user')}<div><h3>Telefone</h3><p>(11) 4000-0000</p></div></div><div class="info-item">${ico('map')}<div><h3>Atendimento demonstrativo</h3><p>Segunda a sexta, das 9h às 18h</p></div></div><button class="btn btn-dark full" data-action="open-chat">${ico('chat')} Conversar com a Lila</button></div><div class="contact-card" style="margin-top:20px"><h2>Dúvidas frequentes</h2>${[['Como funciona a Lila Glam?','A Lila oferece respostas demonstrativas e uma experiência local de cor com questionário. Não há IA conectada nesta versão.'],['Como funciona o frete?','O frete não é calculado neste protótipo e nenhum produto é enviado.'],['Posso comprar sem entrar na conta?','Você pode navegar e adicionar itens. Para concluir um pedido simulado, precisa entrar ou se cadastrar.'],['Como minhas fotos são usadas?','A foto só é processada localmente na aba e não é enviada ou guardada. O resultado textual pode ficar salvo no navegador.'],['Os pagamentos são reais?','Não. Todos os pagamentos e pedidos desta versão são demonstrações.']].map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></aside></div></main>`;}
function chatWidget(){return `${ui.chat?`<div class="chat-panel" role="dialog" aria-label="Conversa com Lila Glam"><div class="chat-head"><img src="${encodeURI(REAL_IMAGES.brand.lila[0])}" alt=""/><div><strong>Lila Glam ✨</strong><small>Assistente demonstrativa • respostas guiadas</small></div><button data-action="close-chat" aria-label="Fechar conversa">${ico('close')}</button></div><div class="chat-messages" id="chat-messages">${ui.chatMessages.map(m=>`<div class="chat-message ${m.from==='me'?'mine':''}">${esc(m.text)}</div>`).join('')}</div><div class="chat-chips">${['Como funciona o frete?','Qual blush escolher?','Como funciona a Glamix?','Análise de cores'].map(q=>`<button data-action="chat-chip" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="chat-form" class="chat-form"><label class="sr-only" for="chat-input">Mensagem para a Lila</label><input id="chat-input" name="message" autocomplete="off" required placeholder="Pergunte sobre beleza..."/><button type="submit" aria-label="Enviar mensagem">${ico('arrow')}</button></form><div class="chat-footnote">Chat com respostas pré-programadas. Não é IA generativa.</div></div>`:`<button class="chat-fab" data-action="open-chat" aria-label="Abrir chat da Lila Glam"><img src="${encodeURI(REAL_IMAGES.brand.lila[0])}" alt=""/><span>Fale com a Lila! <small>Seu glow começa aqui ✨</small></span></button>`}`;}
function answerChat(question){const q=question.toLocaleLowerCase('pt-BR');if(/frete|entrega|cep|envio/.test(q))return 'O frete não é calculado neste protótipo, e não há entrega real. O resumo mostra apenas o valor dos produtos.';if(/cupom|desconto|promo|oferta/.test(q))return 'Os preços exibidos são os valores informados para o catálogo. Não há cupons nem descontos ativos nesta demonstração.';if(/glamix|impressora|cartucho|refil/.test(q))return 'A Glamix é uma impressora de maquiagem conectada a um aplicativo. Usa cinco cartuchos de pigmentos para criar tonalidades personalizadas. Conheça a máquina, o kit e os refis na linha tecnológica!';if(/blush|rosa|maquiagem|tom|subtom|pele|recomend/.test(q))return 'Temos blush em bastão, líquido e paleta, cada um com cinco opções. A análise de coloração oferece três sugestões conforme suas preferências.';if(/lábio|labio|gloss|oil/.test(q))return 'Conheça o Lip Gloss Tradicional com seis cores e o Lip Oil Fruits com cinco opções inspiradas em frutas.';if(/análise|analise|colora|fotografia|foto|ia|inteligência/.test(q))return 'Na página Lila Glam você envia uma foto com consentimento, recebe uma estimativa visual local, responde seis perguntas e vê sugestões. Esta versão não usa IA real nem envia fotos ao servidor.';if(/pagamento|pix|cartão|cartao|boleto|compra/.test(q))return 'Você pode montar o carrinho sem login e concluir um pedido simulado após entrar. Nenhuma cobrança real é realizada.';if(/oi|olá|ola|bom dia|boa tarde|boa noite/.test(q))return 'Oie! 💜 Pergunte sobre blush, lábios, Glamix, frete ou análise de cores.';return 'Posso ajudar com os produtos TechGlam, a Glamix, frete demonstrativo e a análise de coloração. O que você gostaria de saber?';}
function sendChat(msg){const text=msg.trim().slice(0,500);if(!text)return;ui.chat=true;ui.chatMessages.push({from:'me',text});ui.chatMessages.push({from:'bot',text:answerChat(text)});render(false);const box=document.querySelector('#chat-messages');if(box)box.scrollTop=box.scrollHeight;}
function drawer(){if(ui.drawer!=='cart')return '';const t=totals();return `<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-label="Seu carrinho" aria-modal="true"><div class="drawer-header"><h2>Minha sacola (${cartCount()})</h2><button class="drawer-close" data-action="close-drawer" aria-label="Fechar">${ico('close')}</button></div>${t.cart.length?`${t.cart.map(it=>cartLine(it,true)).join('')}<div class="drawer-footer"><div class="between"><span>Produtos</span><strong>${money(t.subtotal)}</strong></div><div class="spacer"></div><button class="btn btn-dark full" data-action="drawer-to-cart">Ver carrinho ${ico('arrow')}</button></div>`:`<div class="drawer-empty">${ico('bag')}<h3>Por aqui ainda não tem brilho.</h3><p>Escolha seus favoritos e monte sua sacola.</p><button class="btn btn-primary" data-action="drawer-to-catalog">Explorar catálogo</button></div>`}</aside>`;}
function render(shouldScroll=false){let route=navRoute();if(route.startsWith('produto/'))route='produto';const name=route.split('?')[0];const id=navRoute().split('/')[1];const contents=name==='inicio'||name===''?home():name==='catalogo'?catalog():name==='glamix'?glamixPage():name==='ofertas'?catalog():name==='produto'?productPage(id):name==='carrinho'?cartPage():name==='favoritos'?favoritesPage():name==='checkout'?checkoutPage():name==='login'?loginPage():name==='conta'?accountPage():name==='pedido'?successPage():name==='lila'?lilaPage():name==='sobre'?aboutPage():name==='contato'?contactPage():notFound();document.querySelector('#app').innerHTML=header()+contents+footer()+chatWidget();document.querySelector('#overlay-root').innerHTML=drawer();document.title=(name==='inicio'?'Tecnologia que Realça seu Brilho':({catalogo:'Catálogo',glamix:'Glamix',produto:'Produto',carrinho:'Carrinho',favoritos:'Favoritos',checkout:'Finalizar pedido',login:'Entrar',conta:'Minha conta',pedido:'Pedido simulado',lila:'Lila Glam',sobre:'Quem Somos',contato:'Contato'}[name]||'TechGlam'))+' | TechGlam';if(shouldScroll)window.scrollTo({top:0,behavior:'instant'});if(ui.chat){const scroll=document.querySelector('#chat-messages');if(scroll)scroll.scrollTop=scroll.scrollHeight;}document.body.style.overflow=ui.drawer?'hidden':'';}
function parseCatalogRoute(){const raw=navRoute();if(!raw.startsWith('catalogo'))return;const params=new URLSearchParams(raw.split('?')[1]||'');ui.filters.category=CATEGORIES.includes(params.get('categoria'))?params.get('categoria'):'Todas';ui.filters.search=params.get('busca')||'';}
function resetAnalysisUI(){if(ui.analysis.photoUrl)URL.revokeObjectURL(ui.analysis.photoUrl);ui.analysis={stage:'photo',fileName:'',photoUrl:'',photoData:null,consent:false,tone:'médio',undertone:'neutro',question:0,answers:[],processing:false};}
function hBytes(buf){return Array.from(new Uint8Array(buf),x=>x.toString(16).padStart(2,'0')).join('');}
function bHex(s){return new Uint8Array(s.match(/.{2}/g).map(b=>parseInt(b,16)));}
async function hashPass(password,salt){if(!globalThis.crypto?.subtle)throw Error('Autenticação demonstrativa requer localhost/HTTPS e um navegador moderno.');const source=new TextEncoder().encode(password);const key=await crypto.subtle.importKey('raw',source,'PBKDF2',false,['deriveBits']);const out=await crypto.subtle.deriveBits({name:'PBKDF2',salt:bHex(salt),iterations:120000,hash:'SHA-256'},key,256);return hBytes(out);}
function newSalt(){return hBytes(crypto.getRandomValues(new Uint8Array(16)));}
function loginSuccess(email){const ac=db.accounts[email];if(!ac)return;mergeGuestIntoAccount(ac);db.session=email;save();toast(`Boas-vindas, ${ac.name.split(' ')[0]}! 💜`);const dest=ui.authReturn||'conta';ui.authReturn='';goto(dest);}
async function analyzeFile(file){if(!ui.analysis.consent){toast('Marque o consentimento antes de escolher a foto.','error');return;}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Formato inválido. Use JPG, PNG ou WebP.','error');return;}if(file.size>6*1024*1024){toast('A foto deve ter no máximo 6 MB.','error');return;}const a=ui.analysis;if(a.photoUrl)URL.revokeObjectURL(a.photoUrl);a.photoUrl=URL.createObjectURL(file);a.fileName=file.name.slice(0,60);a.processing=true;render(false);try{const result=await estimateSkinColor(a.photoUrl);a.photoData=result;a.tone=result.tone;a.undertone=result.undertone;toast('Estimativa cromática local concluída. Você pode ajustar o resultado.');}catch(e){console.error(e);a.photoData={skinColor:'#bf9587'};a.tone='médio';a.undertone='neutro';toast('Não foi possível analisar os pixels. Ajuste as opções manualmente.','error');}finally{a.processing=false;render(false);}}
function estimateSkinColor(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{try{const canvas=document.createElement('canvas');const w=160,h=160;canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0,w,h);const {data}=ctx.getImageData(0,0,w,h);const colors=[];for(let y=47;y<111;y+=3){for(let x=52;x<108;x+=3){const i=(y*w+x)*4,r=data[i],g=data[i+1],b=data[i+2],alpha=data[i+3];const max=Math.max(r,g,b),min=Math.min(r,g,b),light=(r+g+b)/3;if(alpha<220||light<55||light>239||max-min>105)continue;colors.push([r,g,b]);}}
 if(colors.length<18)throw new Error('A imagem não tem pixels de referência suficientes.');const median=ch=>{const s=colors.map(c=>c[ch]).sort((a,b)=>a-b);return s[Math.floor(s.length/2)]};const [r,g,b]=[median(0),median(1),median(2)];const lum=.2126*r+.7152*g+.0722*b;const tone=lum>170?'claro':lum>120?'médio':'profundo';const undertone=r-g>17&&g-b>5?'quente':b>r-3?'frio':'neutro';resolve({skinColor:`rgb(${r}, ${g}, ${b})`,tone,undertone});}catch(e){reject(e);}};im.onerror=()=>reject(new Error('Imagem inválida'));im.src=url;});}
async function handleSubmit(e){const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const values=Object.fromEntries(new FormData(form).entries());
 if(form.id==='global-search'||form.id==='mobile-search'){ui.filters.search=String(values.q||'').trim();ui.filters.category='Todas';ui.filters.sort='featured';goto('catalogo?busca='+encodeURIComponent(ui.filters.search));return;}
 if(form.id==='newsletter-form'){const email=String(values.email||'').trim().toLowerCase();if(!db.newsletter.includes(email))db.newsletter.push(email);save();form.reset();toast('E-mail salvo nesta demonstração. Nenhum newsletter será enviado.');return;}


 if(form.id==='chat-form'){sendChat(values.message||'');return;}
 if(form.id==='register-form'){try{const name=String(values.name||'').trim();const email=String(values.email||'').trim().toLowerCase();const pass=String(values.password||'');if(name.length<2||pass.length<8){toast('Confira nome e senha (mínimo 8 caracteres).','error');return;}if(db.accounts[email]){toast('Este e-mail já possui cadastro demonstrativo.','error');return;}const salt=newSalt();const passHash=await hashPass(pass,salt);db.accounts[email]={email,name,salt,passHash,cart:[],favorites:[],orders:[],analysis:null,address:{}};loginSuccess(email);}catch(err){toast(err.message,'error');}return;}
 if(form.id==='login-form'){const email=String(values.email||'').trim().toLowerCase();const p=db.accounts[email];if(!p){toast('Conta não encontrada nesta demonstração. Crie uma conta primeiro.','error');return;}try{if(await hashPass(String(values.password||''),p.salt)!==p.passHash){toast('Senha incorreta.','error');return;}loginSuccess(email);}catch(err){toast(err.message,'error');}return;}
 if(form.id==='recover-form'){const email=String(values.email||'').trim().toLowerCase(),p=db.accounts[email];if(!p){toast('Não encontramos esse cadastro local.','error');return;}try{const salt=newSalt();p.salt=salt;p.passHash=await hashPass(String(values.password||''),salt);save();ui.authMode='login';render(false);toast('Senha local alterada (demo, sem verificação de identidade).');}catch(err){toast(err.message,'error');}return;}
 if(form.id==='profile-form'){const ac=account();if(!ac)return;ac.name=String(values.name||'').trim();ac.phone=String(values.phone||'').trim();ac.address={...ac.address,street:String(values.street||''),number:String(values.number||''),city:String(values.city||''),state:String(values.state||'').toUpperCase()};save();render(false);toast('Dados de demonstração atualizados.');return;}
 if(form.id==='checkout-form'){if(!account()){ui.authReturn='checkout';goto('login');return;}const zipcode=String(values.cep||'').replace(/\D/g,'');if(!/^\d{8}$/.test(zipcode)){toast('CEP inválido.','error');return;}db.cep=zipcode.slice(0,5)+'-'+zipcode.slice(5);const t=totals();if(!t.cart.length){goto('catalogo');return;}const ac=account();ac.name=String(values.name||'').trim();ac.phone=String(values.phone||'').trim();ac.address={cep:db.cep,street:String(values.street||''),number:String(values.number||''),city:String(values.city||''),state:String(values.state||'').toUpperCase()};const id='TG-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-7);(ac.orders??=[]).unshift({id,date:new Date().toISOString(),items:t.cart.map(x=>({...x,name:itemById(x.id)?.name})),subtotal:t.subtotal,discount:t.discount,shipping:t.ship,total:t.total,payment:String(values.payment)});ac.cart=[];db.coupon='';db.lastOrderId=id;ui.orderDone=id;save();toast('Pedido de demonstração registrado!');goto('pedido');return;}
 if(form.id==='contact-form'){db.messages.push({name:String(values.name||'').trim(),email:String(values.email||'').trim(),subject:String(values.subject||''),message:String(values.message||'').trim(),date:new Date().toISOString()});save();form.reset();toast('Mensagem registrada no navegador. Não houve envio real.');return;}
}
function handleClick(e){const target=e.target.closest('[data-action]');if(!target)return;const act=target.dataset.action,id=target.dataset.id,variantId=target.dataset.variantId||null;if(act==='view-product'||act==='go-category'){if(act==='go-category')goto(target.dataset.category==='Linha Tecnológica TechGlam'?'glamix':'catalogo?categoria='+encodeURIComponent(target.dataset.category));else{ui.detailQty=1;ui.detailProductId=null;ui.detailImageId=null;goto('produto/'+id);}return;}
 if(act==='glamix-step'){const index=Number(target.dataset.step);if(Number.isInteger(index)&&index>=0&&index<GLAMIX_STEPS.length){ui.glamixStep=index;ui.glamixPart=GLAMIX_STEPS[index].part;render(false);document.querySelector('[data-action="glamix-step"][data-step="'+index+'"]')?.focus();}return;}if(act==='glamix-part'){if(GLAMIX_PARTS[target.dataset.part]){const index=[...document.querySelectorAll('.glamix-machine-visual')].indexOf(target.closest('.glamix-machine-visual'));ui.glamixPart=target.dataset.part;render(false);document.querySelectorAll('[data-action="glamix-part"][data-part="'+ui.glamixPart+'"]')[index]?.focus();}return;}if(act==='toggle-menu'){ui.menu=!ui.menu;render(false);return;}if(act==='nav-account'){ui.authReturn='conta';goto(account()?'conta':'login');return;}if(act==='go-favs'){goto('favoritos');return;}
 if(act==='drawer-cart'){ui.drawer='cart';render(false);return;}if(act==='close-drawer'){ui.drawer='';render(false);return;}if(act==='drawer-to-cart'){ui.drawer='';goto('carrinho');return;}if(act==='drawer-to-catalog'){ui.drawer='';goto('catalogo');return;}
 if(act==='add-cart'){const p=itemById(id);if(p?.variants?.length>1){ui.detailProductId=null;ui.detailImageId=null;goto('produto/'+id);}else addToCart(id,p?.variants?.[0]?.id||null,1);return;}if(act==='favorite'){favorite(id);return;}if(act==='change-qty'){changeQty(id,variantId,Number(target.dataset.delta));return;}if(act==='remove-cart'){const cart=activeCart(),i=cart.findIndex(it=>it.id===id&&it.variantId===variantId);if(i>=0){cart.splice(i,1);save();render(false);toast('Produto removido do carrinho.');}return;}
 if(act==='clear-cart'){activeCart().splice(0);save();render(false);toast('Carrinho esvaziado.');return;}if(act==='checkout'){if(!account()){ui.authReturn='checkout';ui.authMode='login';toast('Faça login ou cadastre-se para finalizar. Seu carrinho será preservado.');goto('login');}else goto('checkout');return;}
 if(act==='clear-filters'){ui.filters={category:'Todas',tone:'todos',maxPrice:2000,sort:'featured',search:''};goto('catalogo');render(false);return;}if(act==='toggle-filters'){ui.filterOpen=!ui.filterOpen;render(false);return;}
 if(act==='choose-variant'){const p=itemById(ui.detailProductId),variant=variantById(p,variantId);if(variant)setDetailImage(variant.images[0].id);return;}if(act==='gallery-step'){stepDetailImage(Number(target.dataset.step));return;}if(act==='gallery-image'){setDetailImage(target.dataset.imageId);return;}if(act==='detail-plus'){ui.detailQty=Math.min(99,ui.detailQty+1);render(false);return;}if(act==='detail-minus'){ui.detailQty=Math.max(1,ui.detailQty-1);render(false);return;}if(act==='add-detail'){addToCart(id,selectedVariant(itemById(id))?.id||null,ui.detailQty);return;}
 if(act==='auth-mode'){ui.authMode=target.dataset.mode;render(false);return;}if(act==='logout'){db.session=null;ui.authReturn='';db.coupon='';save();goto('inicio');toast('Você saiu da sua conta de demonstração.');return;}if(act==='account-tab'){ui.accountTab=target.dataset.tab;render(false);return;}
 if(act==='open-chat'){ui.chat=true;render(false);const field=document.querySelector('#chat-input');if(field)field.focus();return;}if(act==='close-chat'){ui.chat=false;render(false);return;}if(act==='chat-chip'){sendChat(target.dataset.question);return;}
 if(act==='analysis-next'){if(!ui.analysis.photoUrl||!ui.analysis.consent){toast('Selecione uma foto e confirme o consentimento.','error');return;}ui.analysis.stage='quiz';ui.analysis.question=0;render(false);return;}
 if(act==='quiz-answer'){ui.analysis.answers[ui.analysis.question]=Number(target.dataset.option);render(false);return;}
 if(act==='quiz-back'){if(ui.analysis.question>0)ui.analysis.question--;else ui.analysis.stage='photo';render(false);return;}
 if(act==='quiz-next'){const a=ui.analysis;if(a.answers[a.question]===undefined){toast('Escolha uma alternativa para continuar.','error');return;}if(a.question<QUESTIONS.length-1){a.question++;render(false);}else{const result=makeRecommendations(a);if(account())account().analysis=result;else db.guestAnalysis=result;save();a.stage='result';if(a.photoUrl){URL.revokeObjectURL(a.photoUrl);a.photoUrl='';}render(false);toast('Suas sugestões da Lila estão prontas!');}return;}
 if(act==='reset-analysis'){resetAnalysisUI();render(false);return;}
 if(act==='delete-analysis'){if(account()){account().analysis=null;save();render(false);toast('Resultado da Lila excluído deste navegador.');}return;}
 if(act==='delete-account'){if(account()&&window.confirm('Excluir permanentemente este cadastro local, seus favoritos e pedidos demonstrativos?')){delete db.accounts[db.session];db.session=null;db.coupon='';save();goto('inicio');toast('Cadastro local excluído.');}return;}
}
function handleChange(e){const t=e.target;if(t.dataset.filter){const k=t.dataset.filter;if(k==='maxPrice')ui.filters[k]=Number(t.value);else ui.filters[k]=t.value;render(false);return;}if(t.id==='photo-consent'){ui.analysis.consent=t.checked;if(!t.checked&&ui.analysis.photoUrl){resetAnalysisUI();}render(false);return;}if(t.id==='photo-input'&&t.files?.[0]){analyzeFile(t.files[0]);return;}if(t.dataset.analysis){ui.analysis[t.dataset.analysis]=t.value;return;}}
window.addEventListener('hashchange',()=>{parseCatalogRoute();ui.menu=false;ui.drawer='';render(true);});
document.addEventListener('submit',e=>{handleSubmit(e).catch(err=>{console.error(err);toast('Não foi possível concluir a operação.','error');});});
document.addEventListener('click',handleClick);
document.addEventListener('change',handleChange);
let galleryPointer=null;
document.addEventListener('pointerdown',e=>{const gallery=e.target.closest?.('.gallery-window');if(gallery&&e.isPrimary&&!e.target.closest?.('button')){galleryPointer={id:e.pointerId,x:e.clientX,y:e.clientY};gallery.setPointerCapture?.(e.pointerId);}});
document.addEventListener('pointerup',e=>{if(!galleryPointer||e.pointerId!==galleryPointer.id)return;const dx=e.clientX-galleryPointer.x,dy=e.clientY-galleryPointer.y;galleryPointer=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2&&e.target.closest?.('.gallery-window'))stepDetailImage(dx<0?1:-1);});
document.addEventListener('pointercancel',()=>{galleryPointer=null;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(ui.drawer){ui.drawer='';render(false);}else if(ui.chat){ui.chat=false;render(false);}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action="view-product"]')){e.preventDefault();e.target.click();}if(e.target.matches?.('.gallery-window')&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();stepDetailImage(e.key==='ArrowRight'?1:-1);}});
window.addEventListener('beforeunload',()=>{if(ui.analysis.photoUrl)URL.revokeObjectURL(ui.analysis.photoUrl);});
function checkoutItemReview(t){return `<div class="checkout-items"><h2>Itens do pedido</h2>${t.cart.map(it=>{const p=itemById(it.id),variant=cartVariant(it,p);if(!p)return '';const name=it.name||p.name,variantName=it.variantName||variant?.name;return `<div class="checkout-item"><img src="${esc(it.image||variant?.images[0]?.src||p.images?.[0]?.src||img(p.id))}" alt=""/><div><strong>${esc(name)}${variantName?` — ${esc(variantName)}`:''}</strong><span>${variantName?`Opção: ${esc(variantName)} • `:''}Quantidade: ${it.qty}</span></div><b>${money(unitPrice(it,p)*it.qty)}</b></div>`;}).join('')}</div>`;}
function orderItemLabel(it){const p=itemById(it.id),variant=cartVariant(it,p),name=it.name||p?.name||'Produto',variantName=it.variantName||variant?.name;return `<li>${esc(name)}${variantName?` — ${esc(variantName)}`:''} · ${Number(it.qty)||1} un.</li>`;}
function productPage(id){
 const p=itemById(id);if(!p)return notFound();if(ui.detailProductId!==id){ui.detailProductId=id;ui.detailImageId=null;ui.detailQty=1;}
 const images=productImages(p),image=selectedImage(p),index=images.findIndex(x=>x.id===image.id),variant=variantById(p,image.variantId);
 const gallery=`<div class="product-gallery" data-product="${p.id}"><div class="product-detail-media gallery-window" tabindex="0" aria-label="Imagens de ${esc(p.name)}. Use as setas para navegar."><div class="gallery-track" style="transform:translateX(-${index*100}%)">${images.map((slide,i)=>`<div class="gallery-slide" data-image-id="${esc(slide.id)}" data-variant-id="${esc(slide.variantId||'')}" aria-hidden="${i!==index}"><img src="${esc(slide.src)}" alt="${esc(slide.alt)}" loading="${i===index?'eager':'lazy'}" decoding="async" draggable="false"/></div>`).join('')}</div>${images.length>1?`<button class="gallery-arrow prev" data-action="gallery-step" data-step="-1" aria-label="Imagem anterior">${ico('arrow')}</button><button class="gallery-arrow next" data-action="gallery-step" data-step="1" aria-label="Próxima imagem">${ico('arrow')}</button>`:''}</div>${images.length>1?`<div class="gallery-dots" aria-label="Escolher imagem do produto">${images.map((slide,i)=>`<button data-action="gallery-image" data-image-id="${esc(slide.id)}" class="${i===index?'selected':''}" aria-label="Imagem ${i+1} de ${images.length}${slide.variantId?` — ${esc(variantById(p,slide.variantId)?.name||'')}`:''}" aria-current="${i===index}"></button>`).join('')}</div>`:''}<p class="gallery-caption" id="gallery-caption" aria-live="polite">${esc(image.alt)}${images.length>1?` • ${index+1} de ${images.length}`:''}</p></div>`;
 return `<main><div class="container"><div class="product-detail">${gallery}<div class="product-detail-info"><div class="breadcrumbs"><a href="#inicio">Início</a> / <a href="#catalogo">Produtos</a> / ${esc(p.category)}</div><span class="eyebrow">TECHGLAM • ${esc(p.category)}</span><h1>${esc(p.name)}</h1><p class="lead" style="margin-top:21px">${esc(p.desc)}</p><div class="detail-price" id="detail-price">${money(p.price)}</div><p class="tiny text-muted">Fotos do produto • compra demonstrativa</p>${p.variants.length?`<div class="detail-option"><h4>Opção: <span id="shade-label" aria-live="polite">${esc(variant?.name||'')}</span></h4><p id="variant-description" class="variant-description">${esc(variant?.description||'')}</p><div class="color-picker" role="group" aria-label="Escolher opção de ${esc(p.name)}">${p.variants.map(v=>`<button data-action="choose-variant" data-variant-id="${esc(v.id)}" class="${variant?.id===v.id?'selected':''}" style="background:${esc(v.swatch)}" title="${esc(v.name)}" aria-label="Selecionar ${esc(v.name)}" aria-pressed="${variant?.id===v.id}"></button>`).join('')}</div><div class="variant-list">${p.variants.map(v=>`<button data-action="choose-variant" data-variant-id="${esc(v.id)}" class="variant-name ${variant?.id===v.id?'selected':''}" aria-pressed="${variant?.id===v.id}">${esc(v.number)} ${esc(v.name)}</button>`).join('')}</div></div>`:''}<div class="detail-quantity"><div class="qty-ctrl"><button data-action="detail-minus" aria-label="Diminuir quantidade">${ico('minus')}</button><span>${ui.detailQty}</span><button data-action="detail-plus" aria-label="Aumentar quantidade">${ico('plus')}</button></div></div><div class="flex" style="align-items:stretch;gap:10px"><button class="btn btn-primary" style="flex:1" data-action="add-detail" data-id="${p.id}">${ico('bag')} Adicionar ao carrinho</button><button class="btn btn-outline" data-action="favorite" data-id="${p.id}" aria-label="Favoritar produto">${ico('heart')}</button></div>${p.id==='maquina-glamix'?`<div class="detail-info-card"><strong>Como funciona a Glamix</strong><p>Escolha as cores no aplicativo conectado. Os pigmentos dos cinco cartuchos são combinados para preparar a maquiagem, liberada pela parte inferior da máquina. Guarde o produto no recipiente portátil com tampa e use o espelho e o pincel acoplados na aplicação.</p><p>O equipamento acompanha os cinco cartuchos necessários para seu funcionamento.</p><a href="#glamix" class="text-link">Explore a Glamix em detalhes →</a></div>`:''}</div></div></div><section class="section compact" style="background:#f9f5fa"><div class="container">${sectionHeading('VOCÊ TAMBÉM VAI AMAR','Combine com seu novo favorito')}<div class="product-grid">${PRODUCTS.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div></div></section></main>`;
}
function setDetailImage(imageId){
 const p=itemById(ui.detailProductId),images=p&&productImages(p),index=images?.findIndex(image=>image.id===imageId);
 if(index==null||index<0)return;
 ui.detailImageId=imageId;
 const gallery=document.querySelector('.product-gallery');if(!gallery||gallery.dataset.product!==p.id)return;
 const image=images[index],variant=variantById(p,image.variantId),track=gallery.querySelector('.gallery-track');
 track.style.transform=`translateX(-${index*100}%)`;
 gallery.querySelectorAll('.gallery-slide').forEach(slide=>slide.setAttribute('aria-hidden',String(slide.dataset.imageId!==imageId)));
 gallery.querySelectorAll('.gallery-dots button').forEach(dot=>{const active=dot.dataset.imageId===imageId;dot.classList.toggle('selected',active);dot.setAttribute('aria-current',String(active));});
 gallery.querySelector('#gallery-caption').textContent=`${image.alt}${images.length>1?` • ${index+1} de ${images.length}`:''}`;
 document.querySelectorAll('.color-picker button').forEach(button=>{const active=button.dataset.variantId===variant?.id;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));});
 const label=document.querySelector('#shade-label');if(label)label.textContent=variant?.name||'';
 const desc=document.querySelector('#variant-description');if(desc)desc.textContent=variant?.description||'';document.querySelectorAll('.variant-name').forEach(button=>{const active=button.dataset.variantId===variant?.id;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));});
}
function stepDetailImage(delta){const p=itemById(ui.detailProductId);if(!p)return;const images=productImages(p),index=images.findIndex(image=>image.id===selectedImage(p).id);setDetailImage(images[(index+delta+images.length)%images.length].id);}
parseCatalogRoute();render(false);
})();
